#!/bin/sh
# Necessary synthetic real-writer, private fallback and optional dependency checks only.
test_repo_root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
python3 - "$test_repo_root" <<'PY_REMOTE'
import subprocess,json,base64,sys
from pathlib import Path
base=['sudo','-u','postgres','/srv/workspace','-X','-h','/run/workspace-hub2-postgres','-v','ON_ERROR_STOP=1','-qAt'];db='hub2_v51_stage_contributors_20261007';phases=['', '', '', base64.b64encode(((Path(sys.argv[1])/'migrations/913-project-stage-contributors.sql').read_text()+(Path(sys.argv[1])/'migrations/914-project-contribution-read-budget.sql').read_text()).encode()).decode(), '', '']
assert subprocess.check_output(base+['-d','postgres','-c',"SELECT count(*)FROM pg_database WHERE datname='"+db+"'"],text=True).strip()=='0'
subprocess.run(base+['-d','postgres','-c','CREATE DATABASE '+db],check=True,capture_output=True)
try:
 for i,source in enumerate(phases):
  r=subprocess.run(base+['-d',db],input=base64.b64decode(source).decode(),text=True,capture_output=True)
  if r.returncode:raise RuntimeError('phase:'+str(i)+':'+r.stderr[-1800:])
  if r.stdout.strip():print(r.stdout.strip())
finally:
 subprocess.run(base+['-d','postgres','-c','DROP DATABASE '+db],check=True,capture_output=True)
print(json.dumps({'isolated_database_dropped':True,'production_business_rows_changed':False}))
PY_REMOTE
